55: async function handleAiSpike(req: NextRequest) {
56:   const rateLimit = await checkRateLimit(req, 'spike');
57:   if (!rateLimit.success) {
58:     return NextResponse.json(
59:       { error: 'Rate limit exceeded' },
60:       { status: 429, headers: rateLimit.headers }
61:     );
62:   }
63: 
64:   const apiKey = process.env.GOOGLE_GENERATIVE_AI_API_KEY;
65:   if (!apiKey) {
66:     return NextResponse.json(MOCK_RESPONSE, {
67:       status: 200,
68:       headers: rateLimit.headers,
69:     });
70:   }
71: 
72:   let body: { image?: string; prompt?: string; model?: string } = {};
73:   if (req.method === 'POST') {
74:     try {
75:       body = await req.json();
76:     } catch {
77:       // Body may be empty or invalid JSON
78:     }
79:   }
80: 
81:   const hasImage = Boolean(body.image);
82:   const modelId = body.model || (hasImage
83:     ? process.env.IDENTIFY_MODEL_ID || 'gemini-2.0-flash'
84:     : process.env.FACTS_MODEL_ID || 'gemma-2-9b-it');
85: 
86:   const startTime = Date.now();
87: 
88:   try {
89:     const google = createGoogleGenerativeAI({ apiKey });
90:     const model = google(modelId);
91: 
92:     const userPrompt =
93:       body.prompt ||
94:       'Identify the organism in this image or description. Return up to 3 candidate species with scientific and common names, kind, confidence rating, and Wikipedia article title. If this is a non-organism (inanimate object) or a human person, mark isLivingOrganism as false and refuse identification honestly.';
