97:       | { type: 'text'; text: string }
98:       | { type: 'image'; image: string | URL }
99:     > = [{ type: 'text', text: userPrompt }];
100: 
101:     if (body.image) {
102:       content.push({
103:         type: 'image',
104:         image: body.image,
105:       });
106:     }
107: 
108:     const { object } = await generateObject({
109:       model,
110:       schema: IdentificationResponseSchema,
111:       messages: [
112:         {
113:           role: 'user',
114:           content,
115:         },
116:       ],
117:     });
118: 
119:     const latencyMs = Date.now() - startTime;
120: 
121:     return NextResponse.json(
122:       {
123:         success: true,
124:         mock: false,
125:         modelUsed: modelId,
126:         latencyMs,
127:         isLivingOrganism: object.isLivingOrganism,
128:         refusalReason: object.refusalReason,
129:         candidates: object.candidates,
130:       },
131:       { status: 200, headers: rateLimit.headers }
132:     );
