136: 
137:     return NextResponse.json(
138:       {
139:         success: false,
140:         error: error?.message || 'Google AI Studio request failed',
141:         mockFallback: MOCK_RESPONSE,
142:         latencyMs,
143:       },
144:       { status: 502, headers: rateLimit.headers }
145:     );
146:   }
147: }
